import java.util.List;
import java.util.Iterator;

/**
 * A class representing the shared characteristics between Prey
 *
 * @version 26/02/2022
 */
public abstract class Prey extends Animal
{
    /**
     * Create a new prey at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param infected Intial state if the prey is infected or not
     * @param immmune Intial state if the prey is immune or not
     */
    protected Prey(Field field, Location location, boolean infected, boolean immune)
    {
        super(field, location, infected, immune);
        movementProbability = 0.75;
    }

    /**
     * @Override
     * 
     * This is what the prey does most of the time - it may move around, it eats plants, 
     * it may breed, it may get infected with a disease, it may become immune to that disease, 
     * it may die of the disease, it may die of hunger, and it may die of old age.
     * 
     * @param newPrey A list to return newly born prey.
     */
    public void act(List<LivingOrganism> newPrey)
    {
        // Prey sleep at night
        if(Time.isNight()) 
        {
            return;
        }

        super.act(newPrey);
    }

    /**
     * @Override
     * 
     * Look for plants adjacent to the current location.
     * Eats plants till full.
     * 
     * @return Where food was found, or null if it wasn't.
     */
    protected Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext()) 
        {
            Location where = it.next();

            // Get the plant and animal currently at this new location.
            Plant plant = (Plant) field.getObjectAt(where, Plant.class);
            Animal animal = (Animal) field.getObjectAt(where, Animal.class);

            if(animal == null)
            {
                if(plant != null)
                {
                    if(plant.isAlive() && foodLevel < maxFoodLevel)
                    { 
                        // Prey is hungry and plant is availiable so eat
                        // the plant.
                        int plantFoodValue = plant.beEaten();
                        foodLevel += plantFoodValue;

                        return where;
                    }
                }
            }
        }

        return null;
    }
}

import java.util.Random;
import java.util.List;

/**
 * A class representing the shared characteristics between Living Organisms.
 *
 * @version 26/02/2022
 */
public abstract class LivingOrganism
{
    // Whether the organism is alive or not.
    protected boolean alive;
    // The field the organism is stored in.
    protected Field field;
    // The organism's position in the field.
    protected Location location;
    // The food value of itself - how much the hunter's food level increases when eating it.
    protected int foodValue;

    // A shared random number generator to control breeding.
    protected static final Random rand = Randomizer.getRandom();

    /**
     * Creates a new Organism at the location.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    protected LivingOrganism(Field field, Location location) 
    {
        alive = true;
        this.field = field;
        setLocation(location);
    }

    /**
     * Increments the organism's age.
     */
    protected abstract void incrementAge();

    /**
     * Make this organism act - that is: make it do
     * whatever it wants/needs to do.
     * 
     * @param newOrganisms A list to receive newly born organsims.
     */
    protected abstract void act(List<LivingOrganism> newOrganisms);

    /**
     * Check whether the organism is alive or not.
     * @return true if the organism is still alive.
     */
    protected boolean isAlive()
    {
        return alive;
    }

    /**
     * Indicate that the organism is no longer alive.
     * It is removed from the field.
     */
    protected abstract void setDead();

    /**
     * When called, the organism gets eaten and returns the
     * food value of which the organism eating it increases
     * 
     * @return The food value of the organism being eaten.
     */
    protected abstract int beEaten();

    /**
     * Return the organism's location.
     * @return The organism's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the organism at the new location in the given field.
     * 
     * @param newLocation The organism's new location.
     */
    protected abstract void setLocation(Location newLocation);

    /**
     * Check whether or not this Organism is to give birth at this step.
     * New births will be made into free adjacent locations.
     * 
     * @param newOrganisms A list to return newly born Organisms.
     */
    protected abstract void populate(List<LivingOrganism> newOrganisms);

    /**
     * Return the organism's field.
     * 
     * @return The organism's field.
     */
    protected Field getField()
    {
        return field;
    }
}

import java.util.List;
import java.util.Iterator;
/**
 * A class representing shared characteristics of animals.
 *
 * @version 25/02/2022
 */
public abstract class Animal extends LivingOrganism
{
    // Indicates whether an animal is a female or not;
    protected boolean isFemale;    
    // The age at which an animal can start to breed.
    protected int breedingAge;
    // The age to which an animal can live.
    protected int maxAge;
    // The likelihood of an animal breeding.
    protected double breedingProbability;
    // whther the animal is infected or not
    protected boolean infected;
    // The likelihood of an animal having a disease.
    protected double diseaseProbability;
    // The likelihood of an animal catching a disease from another animal
    protected double diseaseSpreadProbability;
    // The likelihood of an animal dying from catching the disease
    protected double deathFromInfectionProbability;
    // The likelihood of an animal becomming immune to the disease
    protected double immuneProbability;
    // whether the animal is immune or not
    protected boolean immune;
    // The maximum number of births.
    protected int maxLitterSize;
    // The animals's age.
    protected int age;
    // The animals's food level, which is increased by eating prey.
    protected int foodLevel;
    // The maximum food level that an animal will eat at. The food level they will stop
    // being hungry at
    protected int maxFoodLevel;
    // Probability that an animal will move at a given step.
    protected double movementProbability;

    /**
     * Create a new animal at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param infected Intial state if the animal is infected or not
     * @param immmune Intial state if the animal is immune or not
     */
    public Animal(Field field, Location location, boolean infected, boolean immune)
    {
        super(field, location);
        alive = true;
        this.infected = infected;
        this.immune = immune;

        diseaseProbability = 0.00000015;
        diseaseSpreadProbability = 0.80;
        deathFromInfectionProbability = 0.13;
        immuneProbability = 0.05;

        isFemale = rand.nextBoolean();
    }

    /**
     * @Override
     * 
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * 
     * @param newAnimals A list to receive newly born animals.
     */
    public void act(List<LivingOrganism> newAnimals)
    {
        incrementAge();
        incrementHunger();

        // checks to see if the animal is going to die from it infection 
        // or become immune
        // if the animal becomes immune then it no longer is infected
        if (!getIsImmune() && getIsInfected()) 
        {
            if(rand.nextDouble() <= deathFromInfectionProbability) 
            {
                setDead();            
            }
            else if(rand.nextDouble() <= immuneProbability) {
                immune = true;
                infected = false;
            }
        }
        // If the animal is immune and not infected, there is a chance
        // of losing immunity.
        else
        {
            if(rand.nextDouble() <= (immuneProbability / 15)) {
                immune = false;
            }
        }

        if(isAlive()) 
        {
            if(!getIsImmune() && !getIsInfected())
            {
                // checks to see if the animal is going to catch a disease from
                // its surroundings.

                if (surroundingsInfected() && rand.nextDouble() <= diseaseSpreadProbability)
                {
                    infected = true;
                }

                // checks to see if the animal is going to get a disease out 
                // of nowhere.
                else if (rand.nextDouble() <= diseaseProbability) 
                {
                    infected = true;           
                }
            }

            // checks to see if the animal is able to give birth
            if(this.getIsFemale()) 
            {
                if(canBreed() && rand.nextDouble() <= breedingProbability)
                {
                    populate(newAnimals);
                }
            }

            // Move towards a source of food if found.
            Location newLocation = findFood();

            if(newLocation == null) 
            { 
                Location possibleNewLocation = getField().freeAdjacentLocation(getLocation(), Animal.class);

                if (possibleNewLocation == null) 
                {
                    // no free adjacent locations therefore it is 
                    // overcrowded
                    if (rand.nextDouble() < 0.3) 
                    {
                        setDead();
                    }
                }

                // No food found and there is a free location - move there.
                if (rand.nextDouble() <= movementProbability) 
                {
                    newLocation = possibleNewLocation;
                }
            }

            // Move to new location
            if(newLocation != null)
            { 
                setLocation(newLocation);
            }
        }
    }

    /**
     * Look for food adjacent to the current location.
     * Only the first live prey or plant is eaten.
     * 
     * @return Where food was found, or null if it wasn't.
     */
    abstract protected Location findFood();

    /**
     * @Override
     * 
     * Indicate that the animal is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;

        if(location != null) 
        {
            field.clear(location, Animal.class);
            location = null;
        }

        if (this.getClass().equals(Lion.class) || this.getClass().equals(Cheetah.class)){
            location = null;
        }
    }

    /**
     * @Override
     * 
     * When called, the animal is killed and returns
     * its food value.
     * 
     * @return The food value of the animal eaten.
     */
    protected int beEaten() 
    {
        setDead();

        return foodValue;
    }

    /**
     * @Override
     * 
     * Place the animal at the new location in the given field.
     * 
     * @param newLocation The animal's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) 
        {
            if(field.getObjectAt(location, Animal.class) != null)
            {
                field.clear(location, Animal.class);
            }

import java.util.List;
import java.util.Iterator;
/**
 * A class representing the shared characteristics between predators
 *
 * @version 25/02/2022
 */
public abstract class Predator extends Animal
{
    // The likelihood of the predator catching its prey
    protected double preyCatchingProbability;

    /**
     * Create a new predator at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param infected : intial state if the prey is infected or not
     * @param immmune : intial state if the prey is immune or not
     */
    protected Predator(Field field, Location location, boolean isInfected, boolean isImmune)
    {
        super(field, location, isInfected, isImmune);
        movementProbability = 0.8;
    }

    /**
     * @Override
     * 
     * This is what the predators does most of the time - it may move around, it eats prey, 
     * it may breed, it may get infected with a disease, it may become immune to that disease, 
     * it may die of the disease, it may die of hunger, and it may die of old age.
     * 
     * @param newPredators A list to return newly born prey.
     */
    public void act(List<LivingOrganism> newPredators)
    {
        // Predators have a lower chance of acting when its night
        if(Time.isNight()) 
        {
            if (rand.nextDouble() > 0.25)
            {
                return;
            }
        }

        // Predators have a lower chance of acting when its foggy
        if (Weather.getWeather() == Weather.WeatherType.Foggy) 
        {
            if (rand.nextDouble() > 0.50)
            {
                return;
            }
        }

        super.act(newPredators);
    }

    /**
     * @Override
     * 
     * Look for prey adjacent to the current location.
     * Eats prey till full.
     * Predators may catch the prey's disease if eaten.
     * 
     * @return Where food was found, or null if it wasn't.
     */
    protected Location findFood()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext()) 
        {
            Location where = it.next();
            Object animal = field.getObjectAt(where, Animal.class);

            if(animal instanceof Prey) 
            {
                Prey prey = (Prey) animal;
                if(prey.isAlive() && foodLevel < maxFoodLevel && rand.nextDouble() < preyCatchingProbability) 
                { 
                    // Predator is hungry and prey is availiable so eat
                    // the prey.
                    int preyFoodValue = prey.beEaten();
                    foodLevel += preyFoodValue;

                    // if the prey being eaten is infected then the predator most likely
                    // gets infected
                    if (prey.getIsInfected() && !getIsImmune() && rand.nextDouble() <= diseaseSpreadProbability)
                    {
                        this.infected = true; 
                    }

                    return where;
                }
            }
        }

        return null;
    }
}

