     * Define a color to be used for the given class.
     *
     * @param newClass The new Class' object.
     * @param classColor The color to be used for the given class.
     * @param textColor The color to be used for the text in the class key.
     */
    public void setColor(Class newClass, Color classColor, Color textColor)
    {
        colors.put(newClass, classColor);

        // Creates label of the appropriate color and text to be
        // displayed by the class key.
        JLabel newClassLabel = new JLabel(newClass.getName(), JLabel.CENTER);

        // Adjusts color of the label's text
        newClassLabel.setForeground(textColor);

        newClassLabel.setBackground(classColor);
        newClassLabel.setOpaque(true);

        classKey.add(newClassLabel);
    }

    /**
     * @param animalClass The class to get the colour of.
     * 
     * @return The color to be used for a given class of animal.
     */
    private Color getColor(Class animalClass)
    {
        Color col = colors.get(animalClass);
        if(col == null) {
            // no color defined for this class
            return UNKNOWN_COLOR;
        }
        else {
            return col;
        }
    }

    /**
     * Show the current status of the field.
     * 
     * @param field The field whose status is to be displayed.
     */
    public void showStatus(Field field)
    {
        if(!isVisible()) {
            setVisible(true);
        }

        stepLabel.setText(STEP_PREFIX + Time.getStep());
        timeLabel.setText(TIME_PREFIX + getTimeString());
        weatherLabel.setText(WEATHER_PREFIX + Weather.getWeather() + "  ");
        stats.reset();

        fieldView.preparePaint();

        // Used to tally up the respective counts.
        int numberOfInfected = 0;
        int numberOfImmune = 0;

        for(int row = 0; row < field.getDepth(); row++) 
        {
            for(int col = 0; col < field.getWidth(); col++) 
            {
                Animal animal = (Animal) field.getObjectAt(row, col, Animal.class);
                Plant plant = (Plant) field.getObjectAt(row, col, Plant.class);

                if(animal != null) 
                {
                    stats.incrementCount(animal.getClass());
                    fieldView.drawMark(col, row, getColor(animal.getClass()));

                    // Update the infected and immune counts
                    if (animal.getIsInfected())
                    {
                        numberOfInfected++;
                    }

                    if (animal.getIsImmune())
                    {
                        numberOfImmune++;
                    }
                }
                // Only show the plant if an animal is not present
                else if(plant != null) 
                {
                    fieldView.drawMark(col, row, getColor(plant.getClass()));
                }
                else 
                {
                    Color emptyColor = EMPTY_COLOR;


                if(rand.nextDouble() <= LION_CREATION_PROBABILITY) 
                {
                     animal = (Lion) new Lion(true, field, location, false, false);
                }
                else if(rand.nextDouble() <= CHEETAH_CREATION_PROBABILITY)
                {
                     animal = (Cheetah) new Cheetah(true, field, location, false, false);
                }
                else if(rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) 
                {
                     animal = (Zebra) new Zebra(true, field, location, false, false);
                }
                else if(rand.nextDouble() <= GIRAFFE_CREATION_PROBABILITY)
                {
                     animal = (Giraffe) new Giraffe(true, field, location, false, false);
                }
                else if(rand.nextDouble() <= LEMUR_CREATION_PROBABILITY) 
                {
                     animal = (Lemur) new Lemur(true, field, location, false, false);
                }

                if(animal != null) 
                {
                    animals.add(animal);
                }
            }
        }
    }

    /**
     * Pause for a given time.
     * @param millisec  The time to pause for, in milliseconds
     */
    private void delay(int millisec)
    {
        try {
            Thread.sleep(millisec);
        }
        catch (InterruptedException ie) {
            // wake up
        }
    }

    /**
     * Sets the visibility of the buttons in accordance with the current
     * state of the simulation.
     */
    private void buttonToggle() 
    {
        boolean isPaused = Time.getIsPaused();
        boolean isFinished = Time.getIsFinished();

        boolean isStopped = false;
        if (isPaused || isFinished) 
        {
            isStopped = true;
        }

        // Adjust button usability.
        buttons[0].setEnabled(!isFinished);
        buttons[1].setEnabled(isStopped);
        buttons[2].setEnabled(isStopped);
        buttons[3].setEnabled(isStopped);

        // Set the label on the play/pause button.
        if (isStopped) 
        {
            buttons[0].setLabel("Play");   
        }
        else {
            buttons[0].setLabel("Pause");
        }
    }

    /**
     * Used by the quit button to close the application.
     */
    private void quit()
    {
        System.exit(0);
    }
