361	     * Set the shared species-level characteristics for an animal.
362	     */
363	    protected final void configureAnimal(int breedingAge, int maxAge, double breedingProbability,
364	                                         int maxLitterSize, int maxFoodLevel, int foodValue)
365	    {
366	        this.breedingAge = breedingAge;
367	        this.maxAge = maxAge;
368	        this.breedingProbability = breedingProbability;
369	        this.maxLitterSize = maxLitterSize;
370	        this.maxFoodLevel = maxFoodLevel;
371	        this.foodValue = foodValue;
372	    }
373	
374	    /**
375	     * Initialise age and hunger state for either a newborn or a random starting animal.
376	     */
377	    protected final void initializeAgeAndFood(boolean randomAge, int newbornFoodLevel)
378	    {
379	        if (randomAge) 
380	        {
381	            age = rand.nextInt(maxAge);
382	            foodLevel = rand.nextInt(maxFoodLevel);
383	        }
384	        else
385	        {
386	            age = 0;
387	            foodLevel = newbornFoodLevel;
388	        }
389	    }
